{"LimitSingleInstance":true,"SummaryExpression":"","SubPrograms":[],"Variables":[],"Steps":[{"StepRunnerKey":"sys:csscript","InputParams":{"mode":{"VarKey":null,"Value":"normal_roslyn"},"script":{"VarKey":null,"Value":"using System;
using System.Diagnostics;
using System.IO;
using System.Threading;
using System.Windows;
using Quicker.Public;

public static void Exec(IStepContext context)
{
    string root = Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.CommonDocuments),
        "ImeSshSync");
    string launcher = Path.Combine(root, "start-hidden.vbs");
    string stopper = Path.Combine(root, "stop.ps1");

    bool imeRunning = MutexExists(@"Local\ImeSshSync.Ime");
    bool clipboardRunning = MutexExists(@"Local\ImeSshSync.Clipboard");

    try
    {
        if (imeRunning || clipboardRunning)
        {
            if (!File.Exists(stopper))
                throw new FileNotFoundException("找不到停止脚本：" + stopper, stopper);

            RunAndWait("pwsh.exe",
                "-NoLogo -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File \"" + stopper + "\"",
                15000);

            Thread.Sleep(500);
            bool stopped = !MutexExists(@"Local\ImeSshSync.Ime")
                && !MutexExists(@"Local\ImeSshSync.Clipboard");

            MessageBox.Show(
                stopped ? "IME 与双向剪贴板同步已停止。" : "停止命令已执行，但仍检测到同步进程，请运行 status.ps1。",
                "IME/剪贴板同步",
                MessageBoxButton.OK,
                stopped ? MessageBoxImage.Information : MessageBoxImage.Warning);
        }
        else
        {
            if (!File.Exists(launcher))
                throw new FileNotFoundException("找不到启动器：" + launcher, launcher);

            ProcessStartInfo info = new ProcessStartInfo
            {
                FileName = Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.Windows),
                    @"System32\wscript.exe"),
                Arguments = "\"" + launcher + "\"",
                UseShellExecute = false,
                CreateNoWindow = true,
                WindowStyle = ProcessWindowStyle.Hidden,
                WorkingDirectory = root
            };
            Process.Start(info);

            Thread.Sleep(1800);
            bool imeStarted = MutexExists(@"Local\ImeSshSync.Ime");
            bool clipboardStarted = MutexExists(@"Local\ImeSshSync.Clipboard");

            MessageBox.Show(
                imeStarted && clipboardStarted
                    ? "IME 与双向剪贴板同步已启动。"
                    : "启动器已执行，但进程未全部就绪，请运行 status.ps1 查看日志。",
                "IME/剪贴板同步",
                MessageBoxButton.OK,
                imeStarted && clipboardStarted ? MessageBoxImage.Information : MessageBoxImage.Warning);
        }
    }
    catch (Exception ex)
    {
        MessageBox.Show(ex.Message, "IME/剪贴板同步", MessageBoxButton.OK, MessageBoxImage.Error);
    }
}

private static bool MutexExists(string name)
{
    Mutex mutex;
    if (!Mutex.TryOpenExisting(name, out mutex))
        return false;
    mutex.Dispose();
    return true;
}

private static void RunAndWait(string fileName, string arguments, int timeoutMs)
{
    ProcessStartInfo info = new ProcessStartInfo
    {
        FileName = fileName,
        Arguments = arguments,
        UseShellExecute = false,
        CreateNoWindow = true,
        WindowStyle = ProcessWindowStyle.Hidden
    };

    using (Process process = Process.Start(info))
    {
        if (process == null)
            throw new InvalidOperationException("无法启动命令。");
        if (!process.WaitForExit(timeoutMs))
        {
            try { process.Kill(); } catch { }
            throw new TimeoutException("停止命令执行超时。");
        }
        if (process.ExitCode != 0)
            throw new InvalidOperationException("停止命令失败，退出码：" + process.ExitCode);
    }
